/** Divides a parcel's volume in cubic centimetres to give its volumetric weight in kilograms. This is the divisor in force now. */
export const VOLUMETRIC_DIVISOR = 6000;

/** The carrier's volumetric divisors, newest first, each with the first day (UTC) of the parcels it applies to. */
const DIVISOR_SCHEDULE = [
  { from: Date.UTC(2026, 6, 1), divisor: 6000 },
  { from: Date.UTC(2026, 3, 1), divisor: 4000 },
  { from: -Infinity, divisor: 5000 },
];

/** Returns the volumetric divisor that applied to a parcel shipped on the given Date. */
export function volumetricDivisorOn(date) {
  const day = date.getTime();
  return DIVISOR_SCHEDULE.find(({ from }) => day >= from).divisor;
}

